create type public.dispute_status as enum('open','resolved');create type public.dispute_resolution as enum('upheld','corrected','voided');
create table public.result_disputes(id uuid primary key default gen_random_uuid(),result_id uuid not null references public.match_results,club_id uuid not null references public.clubs,opened_by uuid not null references public.players,reason_code text not null,description text not null,status public.dispute_status not null default 'open',resolution public.dispute_resolution,resolution_reason text,resolved_by uuid references public.players,resolved_at timestamptz,created_at timestamptz not null default now(),version bigint not null default 1);create unique index one_open_result_dispute_idx on public.result_disputes(result_id)where status='open';create index dispute_club_status_idx on public.result_disputes(club_id,status,created_at);
create table public.dispute_evidence(dispute_id uuid not null references public.result_disputes on delete cascade,evidence_object_id uuid not null references private.evidence_objects,added_by uuid not null references public.players,created_at timestamptz not null default now(),primary key(dispute_id,evidence_object_id));
alter table public.result_disputes enable row level security;alter table public.dispute_evidence enable row level security;create policy dispute_authorized_read on public.result_disputes for select to authenticated using(opened_by=public.current_player_id()or private.has_club_role(club_id,array['owner','score_official']::public.club_role[]));create policy dispute_evidence_authorized_read on public.dispute_evidence for select to authenticated using(exists(select 1 from public.result_disputes d where d.id=dispute_id));grant select on public.result_disputes,public.dispute_evidence to authenticated;revoke insert,update,delete on public.result_disputes,public.dispute_evidence from anon,authenticated;
create or replace function private.rebuild_competition_after_dispute(p_result_id uuid)returns bigint language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v bigint:=nextval('private.competition_calculation_version');begin update public.player_statistics set calculation_version=v,updated_at=now() where player_id in(select mp.player_id from public.match_results r join public.match_participants mp on mp.match_id=r.match_id where r.id=p_result_id);update public.leaderboard_entries set calculation_version=v where player_id in(select mp.player_id from public.match_results r join public.match_participants mp on mp.match_id=r.match_id where r.id=p_result_id);return v;end$$;revoke all on function private.rebuild_competition_after_dispute(uuid)from public,anon,authenticated;
